import{_ as l,o as i,c as o,ae as b}from"./chunks/framework.BrEqZt6s.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Phenomenology/시험 준비.md","filePath":"philosophy/Phenomenology/시험 준비.md"}'),t={name:"philosophy/Phenomenology/시험 준비.md"};function n(s,r,a,e,g,h){return i(),o("div",null,[...r[0]||(r[0]=[b('<h2 id="_1-현상학의-기획" tabindex="-1">1. 현상학의 기획 <a class="header-anchor" href="#_1-현상학의-기획" aria-label="Permalink to &quot;1. 현상학의 기획&quot;">​</a></h2><ol><li><p>당시 시대비판</p><ol><li>독일관념론<br> 인식의 근거를 세계의 근거로 확장, 근거가 부족<br> 자연주의와 역사주의에 동기를 불어넣음<br> 사변적 반발로 자연주의, 상대주의적 관점으로 역사 주의</li><li>자연주의<br> 모든 것을 자연주의적으로 환원하려는 시도<br> 논리적 법칙은 자연법칙으로 환원될 수 없다<br> 자연 과학으로 설명되지 않는 것을 무리하게 포섭하려함<br> 가령 어떤 논리 체계를 담당하는 자연적 부분이 없더라도 그 논리 체계는 참이다</li><li>역사주의<br> 학문의 객관성을 상실하게 함<br> 어떠한 역사적 배경이 그것을 정당화 해주지는 않음<br> 가령 피타고라스 정리를 발견하게 한 역사적 동기가 그 정리를 정당화 해주지 않음</li><li><strong>형이상학적 관념론과 구별점</strong><br> 모든 존재의 근원이 의식이라는 것이 아니라 모든 인식의 근원이 의식임</li><li><strong>환원주의와 구별점</strong><br> 의식에 대한 탐구만 정당한 것이 아니라 그것이 토대를 제공할 수 있음</li><li><strong>상대주의와 구별점</strong><br> 진리가 의식에 상대적이라는 것이 아니라 진리가 의식에 나타나는 방식과 구조를 ㅊ탐구 해야함</li></ol></li><li><p>현상학의 두가지 속성<br> 인식적 절대성<br> 데카르트의 방식대로 직접적으로 의식되는 것은 의심될 수 없음<br> 인식적 근원성<br> 칸트의 방식대로 모든 것은 의식으로 부터 정당화 됨</p></li></ol><h3 id="_2-기본-개념" tabindex="-1">2. 기본 개념 <a class="header-anchor" href="#_2-기본-개념" aria-label="Permalink to &quot;2. 기본 개념&quot;">​</a></h3><p>반성: 스스로 의식에 대해 직접적으로 관찰하는 것</p><ol><li>의식<br> 어떤 것을 느끼거나 경험하는 것</li><li>대상<br> 의식에 나타나는 것</li><li>노에시스 노에마<br> 의식에 대한 것 , 대상에 대한 것</li><li>지향성<br> 어떤 것에 대한 것이라는 속성</li><li><strong>현상학적 환원</strong><br> 실제 세계에서 그것이 나타나는 의식과 현상으로 눈을 돌림</li><li>에포케<br> 판단 중지, 자연적 속성들에 괄호를 치고 현상학적인 것에 주목</li><li><strong>현상학적 환원 종류 3가지</strong><br> 데카르트적 환원<br> 확실하지 않은 것들에 대해 판단 중지하고 확실한 것으로 눈을 돌림<br> 심리학적 환원<br> 심리학적인 요소인 물리학적 생물학적 요소를 차단하고 순수한 의식으로 눈을 돌림<br> 생활세계적 환원<br> 학문을 통해 나타나는 세계에서 생활세계적 현상으로 눈을 도림</li><li>현상학적 반성<br> 자기 의식에 대한 직접적인 관찰</li><li>본질<br> 그것이 그것이기 위해 필연적으로 가져야하는 속성</li><li>형상적 환원<br> 그것의 다른 속성들을 배제하고 형상에 주목하는 것</li><li>본질 직관<br> 그것을 여러 모습으로 바꿔가면서 그것의 본질을 찾는 것</li><li>의미<br> 대상이 나에게 나타나는 방식</li><li>정립<br> 대상에 대한 태도</li><li>직관<br> 대상을 인식하는 것</li><li><strong>직관 종류 4개</strong><br> 지각 예상 회상 상상<br> 지각: 대상을 지금 여기 있는 것으로 직관<br> 예상: 대상을 언젠가 있을 것으로 직관<br> 회상: 대상이 어딘가 있는 것으로 직관<br> 상상: 대상이 없는 것으로 직관</li><li>지향 체계<br> 지향을 통해 기대를 생성하고 이는 충족과 실망으로 이어짐</li><li><strong>지향 개념</strong><br> 어떤 것이 직관될 것이라는 기대</li><li><strong>명증</strong><br> 정립의 정당화, 또는 정당성</li><li><strong>파악</strong><br> 어떤 것을 경험하면서 또 다른 것을 경험함</li><li><strong>구성</strong><br> 어떤 대상에 대한 인식이 만들어짐</li><li>휠레<br> 감각 자료</li></ol><h3 id="_3-지각" tabindex="-1">3. 지각 <a class="header-anchor" href="#_3-지각" aria-label="Permalink to &quot;3. 지각&quot;">​</a></h3><ol><li>지각 (넓은 의미, 좁은 의미) 지각의 두가지 속성<br> 사물을 인식하는 것<br> 넓은 의미는 대상을 직접적으로 인식<br> 좁은 의미는 사물을 직접적으로 인식</li><li>사물<br> 시공간적, 인과적 속성을 지니는 것</li><li><strong>작용</strong><br> 지향성을 지니는 의식</li><li>회상 예상<br> 간접 명증적 직관</li><li>상상<br> 비 명증적 직관</li><li><strong>파악</strong><br> 어떤 것을 경험하면서 또 다른 것으로 경험, 다른 것으로 해석<br> 자료들이 사물과 사물의 속성으로 인식</li><li><strong>지평</strong><br> 어떤 것이 의식될 때 함께 의식되는 모든 것<br> 내적 지평: 어떤 대상의 부분과 내적 속성<br> 외적 지평: 환경과 외적 속성</li><li><strong>몸 (감각 두개)</strong><br> 운동감각: 신체의 움직임에 대한 감각, 고유 감각 포함<br> 고유감각: 몸 내부에 대한 감각</li><li><strong>기대</strong><br> 어떤 것이 경험 될 것 이라는 믿음</li><li><strong>지각의 구조</strong><br> 시간구성, 공간구성, 인과 구성<br> 시간 구성: 지속 - 순간적인 감각적 성질이 지속적인 감각적 성질로 파악<br> 공간 구성: 환상 - 지속적인 감각적 성질들이 하나의 공간적 형태로 파악<br> 인과 구성: 사물 - 공작적 형태가 하나의 인과적 실체로 파악</li></ol><h3 id="_4-판단" tabindex="-1">4. 판단 <a class="header-anchor" href="#_4-판단" aria-label="Permalink to &quot;4. 판단&quot;">​</a></h3><ol><li>판단<br> 사실에 대한 의식 <ol><li>감각적 경험이 없으면 판단이 일어날 수 없음!</li><li>감각적 경험으로부터만 직관, 명증적 판단이 일어 날 수 있음</li></ol></li><li><strong>추상적 대상</strong><br> 시공간적 속성을 넘어서 있는 대상 <ol><li>직관 비직관 명증 비명증</li><li>종합이 판단의 근원</li></ol></li><li>사실<br> 사태, 어떤 것은 ~한 상태이다로 표현</li><li>사실 인식 단계<br> 전체와 부분의 종합 : 전<br> 명시화 : 전체를 인식하면서 그것의 부분의 속성에 동시에 주목<br> 사실 인식 : 그것을 사실로 받아들임, 기체속성 관계를 인식</li><li><strong>집합</strong><br> 특정한 대상의 모음</li><li><strong>집합 인식 단계</strong><br> 연언의 종합 : 대상들을 하나하나 함께 주목함<br> 집합 인식 : 집합을 인식함</li><li>보편자<br> 여러 대상들이 동시에 가지는 보편적 속성</li><li><strong>보편자 인식 단계</strong><br> 유사한 대상들의 종합: 유사한 대상에 대한 경험이 서로 합치<br> 개별적 판단: 유사한 대상들 각각에 대해 그것이 P라고 판단함<br> 보편자 인식: P의 보편자를 인식함</li></ol><h3 id="_5-의식의-심층" tabindex="-1">5. 의식의 심층 <a class="header-anchor" href="#_5-의식의-심층" aria-label="Permalink to &quot;5. 의식의 심층&quot;">​</a></h3><ol><li><strong>현상학적 시간</strong><br> 대상들이 현재, 과거, 미래의 방식으로 의식되는 방식</li><li><strong>촉발</strong><br> 대상이 주체의 행위를 자극함</li><li><strong>현상학적 시간 3가지 종류</strong><br> 일상적, 근원적<br> 지각, 회상, 예상<br> 인상, 파지, 예지<br> 인상: 자료들이 지금 경험됨<br> 파지: 방금 경험된 자료들이 여전히 의식됨<br> 예지: 아직 경험되지 않은 자료들이 앞서 의식됨</li><li>그것의 속성<br> 파지와 예지는 비직관적</li><li><strong>내적 의식</strong><br> 의식에 관한 의식</li><li><strong>외적 의식</strong><br> 의식 바깥에 대한 의식</li><li>선반성적 자기 의식<br> 내적의식으로 의식이 생기기전, 즉 반성이 이뤄지기전에 의식에 대한 의식이 있음<br> -&gt; 내적 시간의식</li><li><strong>촉발의 방식 2개 설명</strong><br> 융합: 질적으로 같은 자료들이 모여 촉발함<br> 대조: 질적으로 서로 다른 자료 들이 지닌 자료들이 분리되어 촉발함<br> 촉발하는 자료는 촉발하지 않은 자료들의 융합과 대조의 산물<br> 현상학적 무의식에 대한 탐구가 가능</li><li><strong>파지 예지가 직관이 아닌 이유</strong><br> 우리는 음을 들으면서 인상 파지 예지를 함<br> 파지 예지가 직관이라면 지금 경험되는 것이어야함<br> 지금 경험 된다면 우리는 함께 들어야함 그렇지 않음<br> 파지 예지는 직관이 아님</li></ol>',11)])])}const c=l(t,[["render",n]]);export{d as __pageData,c as default};
